<script lang="ts">import{api,rows,text,stamp,type Row}from'../lib/api';import{tr}from'../lib/i18n';import DOMPurify from'dompurify';export let initial:Row={};export let onerror:(e:any)=>void;let data:Row=initial;let busy=false;let edit:Row|null=null;let name='';let hostName='';let note='';let cloud='';let confirm:Row|null=null;let sequence=0;
 $: data=initial;
 $: hostName=data.name??'';
 async function reload(){const ticket=++sequence;try{const next=await api('GetMobile');if(ticket===sequence)data=next}catch(e){onerror(e)}}
 async function act(action:string,values:Row={}){busy=true;try{data=await api('MobileAction',action,values);edit=null;confirm=null}catch(e){onerror(e)}finally{busy=false}}
 function begin(reader:Row){edit=reader;name=reader.name??'';note=reader.note??''}
 async function save(){const id=edit?.id??edit?.reader_id;await act('note',{id,note})}</script>
<section class="surface"><div class="row between"><h3>{tr('启用手机同步')}</h3><button disabled={busy} onclick={()=>act(data.enabled?'disable':'enable')}>{tr(data.enabled?'关闭手机同步':'启用手机同步')}</button></div><label class="field"><span>{tr('本机名称')}</span><input maxlength="40" bind:value={hostName} onblur={()=>{if(hostName&&hostName!==data.name)void act('rename',{name:hostName})}}/></label><p class="muted">{text(data.status)}{data.error?' · '+data.error:''}</p><p class="muted">{tr('增加设备最多 3 台，配对码 5 分钟有效。')}</p><button disabled={busy||!data.enabled||rows(data.readers).length>=3} onclick={()=>act('pair')}>{tr('配对手机')}</button>{#if data.pairing??data.ticket??data.qr_url}{@const pairing=data.pairing??data.ticket??{}}<div class="pairing">{#if pairing.qr_svg??data.qr_svg}<div class="qr">{@html DOMPurify.sanitize(pairing.qr_svg??data.qr_svg,{USE_PROFILES:{svg:true}})}</div>{:else if /^data:image\/(png|svg\+xml);base64,/.test(pairing.qr_url??data.qr_url??'')}<img class="qr" src={pairing.qr_url??data.qr_url} alt={tr('配对手机')}/>{/if}<strong class="mono">{text(pairing.code??data.code)}</strong><small>{stamp(pairing.expires_at)}</small></div>{/if}</section><section class="surface"><h3>{tr('等待配对')}</h3>{#each rows(Array.isArray(data.pending)?data.pending:data.pending?[data.pending]:[]) as pending}<div class="row between mobile-row"><span>{text(pending.name??pending.device_name)}<small>{text(pending.fingerprint)}</small></span><div class="row"><button disabled={busy} onclick={()=>act('approve',{id:pending.id})}>{tr('批准')}</button><button disabled={busy} onclick={()=>act('deny',{id:pending.id})}>{tr('拒绝')}</button></div></div>{/each}{#if !rows(Array.isArray(data.pending)?data.pending:data.pending?[data.pending]:[]).length}<p class="muted">{tr('暂无数据')}</p>{/if}</section><section class="surface"><h3>{tr('已连接设备')}</h3>{#each rows(data.readers) as reader}<div class="row between mobile-row"><div><strong>{text(reader.name??reader.id)}</strong><small>{text(reader.note,'')} · {stamp(reader.last_seen)}</small></div><div class="row"><button onclick={()=>begin(reader)}>{tr('编辑')}</button><button disabled={busy} onclick={()=>confirm=reader}>{tr('撤销')}</button></div></div>{/each}{#if !rows(data.readers).length}<p class="muted">{tr('暂无数据')}</p>{/if}</section><section class="surface"><h3>{tr('只读云端同步')}</h3><form class="row" onsubmit={e=>{e.preventDefault();void act('enroll',{invite:cloud})}}><input bind:value={cloud} placeholder="邀请码 / Invite" aria-label="Invite"/><button disabled={busy||!cloud}>{tr('连接')}</button></form><div class="row"><button disabled={busy} onclick={()=>act('upload')}>{tr('上传只读快照')}</button><button disabled={busy} onclick={()=>act('remove-cloud')}>{tr('移除云端')}</button></div></section>{#if edit}<form class="surface" onsubmit={e=>{e.preventDefault();void save()}}><label class="field"><span>{tr('设备名称')}</span><input maxlength="64" value={name} readonly/></label><label class="field"><span>{tr('备注')}</span><input maxlength="256" bind:value={note}/></label><div class="row"><button disabled={busy}>{tr('保存')}</button><button type="button" onclick={()=>edit=null}>{tr('取消')}</button></div></form>{/if}{#if confirm}<div class="modal-backdrop"><div class="modal"><h2>{tr('撤销')} {text(confirm.name)}</h2><div class="row"><button disabled={busy} onclick={()=>act('revoke',{id:confirm?.id??confirm?.reader_id})}>{tr('撤销')}</button><button onclick={()=>confirm=null}>{tr('取消')}</button></div></div></div>{/if}
